#import "PMContentUI.h"
#import "PMContentStore.h"
#import "PMHookBackend.h"
#include <cmath>
#import <UniformTypeIdentifiers/UniformTypeIdentifiers.h>
@interface PMContentController : UITableViewController <UIDocumentPickerDelegate,UISearchResultsUpdating>
@property(nonatomic,strong) NSDictionary*db;
@property(nonatomic,strong) NSArray*items;
@property(nonatomic,strong) UISegmentedControl*pages;
@property(nonatomic,strong) UISearchController*search;
@property(nonatomic,strong) NSString*selectedChapter;
@property(nonatomic,strong) NSString*imageID;
@property(nonatomic,strong) dispatch_queue_t worker;
@property(nonatomic,assign) BOOL busy;
- (void)reload;
@end
@implementation PMContentController
- (void)viewDidLoad{[super viewDidLoad];self.title=@"PhiMod 谱库 / 章节";self.worker=dispatch_queue_create("phimod.content.import",DISPATCH_QUEUE_SERIAL);self.pages=[[UISegmentedControl alloc]initWithItems:@[@"谱库",@"章节",@"原版"]];self.pages.selectedSegmentIndex=0;[self.pages addTarget:self action:@selector(reload) forControlEvents:UIControlEventValueChanged];self.navigationItem.titleView=self.pages;self.navigationItem.leftBarButtonItem=[[UIBarButtonItem alloc]initWithBarButtonSystemItem:UIBarButtonSystemItemClose target:self action:@selector(close)];self.navigationItem.rightBarButtonItem=[[UIBarButtonItem alloc]initWithBarButtonSystemItem:UIBarButtonSystemItemAdd target:self action:@selector(add)];self.search=[[UISearchController alloc]initWithSearchResultsController:nil];self.search.obscuresBackgroundDuringPresentation=NO;self.search.searchResultsUpdater=self;self.navigationItem.searchController=self.search;self.definesPresentationContext=YES;
 self.toolbarItems=@[[[UIBarButtonItem alloc]initWithTitle:@"导入 ZIP / PEZ" style:UIBarButtonItemStylePlain target:self action:@selector(importFiles)],[[UIBarButtonItem alloc]initWithBarButtonSystemItem:UIBarButtonSystemItemFlexibleSpace target:nil action:nil],[[UIBarButtonItem alloc]initWithTitle:@"应用到游戏" style:UIBarButtonItemStylePlain target:self action:@selector(apply)]];self.navigationController.toolbarHidden=NO;[self reload];}
- (void)message:(NSString*)text {UIAlertController*a=[UIAlertController alertControllerWithTitle:@"PhiMod" message:text preferredStyle:UIAlertControllerStyleAlert];[a addAction:[UIAlertAction actionWithTitle:@"确定" style:UIAlertActionStyleDefault handler:nil]];[self presentViewController:a animated:YES completion:nil];}
- (void)close {if(self.busy){[self message:@"正在处理文件，请等待任务完成"];return;}[self dismissViewControllerAnimated:YES completion:nil];}
- (void)reload {self.db=[PMContentStore.shared snapshot];NSArray*all=self.pages.selectedSegmentIndex==1?self.db[@"chapters"]:self.pages.selectedSegmentIndex==2?[PMHookBackend contentSnapshot][@"chapters"]:self.db[@"songs"];NSMutableArray*filtered=[NSMutableArray new];NSString*q=self.search.searchBar.text.lowercaseString ?: @"";for(NSDictionary*x in all){NSString*hay=[NSString stringWithFormat:@"%@ %@ %@ %@",x[@"title"] ?: x[@"songInfo"][@"title"] ?: x[@"name"],x[@"composer"] ?: @"",x[@"id"] ?: x[@"chapterCode"],x[@"level"] ?: @""];if(!q.length||[hay.lowercaseString containsString:q])[filtered addObject:x];}self.items=filtered;self.navigationItem.prompt=self.busy?@"正在处理文件，结束后将自动刷新":@"编辑保存在本地；应用到游戏会返回章节选择";[self.tableView reloadData];}
- (void)updateSearchResultsForSearchController:(UISearchController*)s{[self reload];}
- (NSInteger)tableView:(UITableView*)table numberOfRowsInSection:(NSInteger)section{return self.items.count;}
- (UITableViewCell*)tableView:(UITableView*)table cellForRowAtIndexPath:(NSIndexPath*)index{UITableViewCell*c=[table dequeueReusableCellWithIdentifier:@"item"];if(!c)c=[[UITableViewCell alloc]initWithStyle:UITableViewCellStyleSubtitle reuseIdentifier:@"item"];NSDictionary*x=self.items[index.row];BOOL chapter=self.pages.selectedSegmentIndex!=0;c.textLabel.text=chapter?(x[@"name"] ?: x[@"songInfo"][@"title"]):x[@"title"];c.detailTextLabel.text=chapter?[NSString stringWithFormat:@"%@ · %lu 首",x[@"id"] ?: x[@"chapterCode"],(unsigned long)[(x[@"songs"] ?: x[@"songInfo"][@"songs"])count]]:[NSString stringWithFormat:@"%@ %@ · %@ · %@",x[@"level"],x[@"difficulty"],x[@"sourceFormat"] ?: @"JSON",x[@"composer"] ?: @""];c.detailTextLabel.numberOfLines=2;c.accessoryType=UITableViewCellAccessoryDisclosureIndicator;NSString*folder=[PMContentStore.shared asset:x[@"id"]];c.imageView.image=folder?[UIImage imageWithContentsOfFile:[folder stringByAppendingPathComponent:@"image.png"]]:nil;return c;}
- (void)sheet:(UIAlertController*)a row:(NSIndexPath*)index{a.popoverPresentationController.sourceView=self.tableView;a.popoverPresentationController.sourceRect=[self.tableView rectForRowAtIndexPath:index];[a addAction:[UIAlertAction actionWithTitle:@"取消" style:UIAlertActionStyleCancel handler:nil]];[self presentViewController:a animated:YES completion:nil];}
- (BOOL)save:(NSDictionary*)db{NSError*e=nil;BOOL ok=[PMContentStore.shared commit:db error:&e];if(!ok)[self message:e.localizedDescription];[self reload];return ok;}
- (void)tableView:(UITableView*)table didSelectRowAtIndexPath:(NSIndexPath*)index{[table deselectRowAtIndexPath:index animated:YES];if(self.busy)return;NSDictionary*x=self.items[index.row];NSString*id=x[@"id"] ?: x[@"chapterCode"];BOOL chapter=self.pages.selectedSegmentIndex!=0;UIAlertController*a=[UIAlertController alertControllerWithTitle:chapter?(x[@"name"] ?: x[@"songInfo"][@"title"]):x[@"title"] message:nil preferredStyle:UIAlertControllerStyleActionSheet];
 [a addAction:[UIAlertAction actionWithTitle:chapter?@"打开原版选曲":@"播放此谱面" style:UIAlertActionStyleDefault handler:^(UIAlertAction*action){NSDictionary*r=[PMHookBackend contentCommand:chapter?@"chapter":@"play" identifier:id slot:[@[@"EZ",@"HD",@"IN",@"AT"]indexOfObject:x[@"level"]]];if([r[@"ok"] boolValue])[self dismissViewControllerAnimated:YES completion:nil];else[self message:r[@"message"]];}]];
 [a addAction:[UIAlertAction actionWithTitle:@"编辑信息" style:UIAlertActionStyleDefault handler:^(UIAlertAction*action){[self edit:x chapter:chapter];}]];
 if(self.pages.selectedSegmentIndex!=2){[a addAction:[UIAlertAction actionWithTitle:@"更换封面（系统文件选择）" style:UIAlertActionStyleDefault handler:^(UIAlertAction*action){self.imageID=id;UIDocumentPickerViewController*p=[[UIDocumentPickerViewController alloc]initForOpeningContentTypes:@[UTTypeImage] asCopy:YES];p.delegate=self;[self presentViewController:p animated:YES completion:nil];}]];[a addAction:[UIAlertAction actionWithTitle:chapter?@"导出章节包":@"导出谱包" style:UIAlertActionStyleDefault handler:^(UIAlertAction*action){[self export:id chapter:chapter];}]];}
 if(!chapter){[a addAction:[UIAlertAction actionWithTitle:@"移动到章节" style:UIAlertActionStyleDefault handler:^(UIAlertAction*action){[self move:id index:index];}]];[a addAction:[UIAlertAction actionWithTitle:@"分组 / 多难度合并" style:UIAlertActionStyleDefault handler:^(UIAlertAction*action){[self group:x];}]];[a addAction:[UIAlertAction actionWithTitle:@"删除谱面（资源移入回收目录）" style:UIAlertActionStyleDestructive handler:^(UIAlertAction*action){NSError*e=nil;if(![PMContentStore.shared removeSong:id error:&e])[self message:e.localizedDescription];[self reload];}]];}else if(self.pages.selectedSegmentIndex==2){[a addAction:[UIAlertAction actionWithTitle:[self.db[@"hiddenChapters"] containsObject:id]?@"恢复章节显示":@"隐藏章节（可在本页恢复）" style:UIAlertActionStyleDefault handler:^(UIAlertAction*action){NSMutableDictionary*d=[[PMContentStore.shared snapshot] mutableCopy];NSMutableArray*h=[d[@"hiddenChapters"] mutableCopy];if([h containsObject:id])[h removeObject:id];else[h addObject:id];d[@"hiddenChapters"]=h;[self save:d];}]];}else{[a addAction:[UIAlertAction actionWithTitle:@"导入谱包到此章节" style:UIAlertActionStyleDefault handler:^(UIAlertAction*action){self.selectedChapter=id;[self importFiles];}]];[a addAction:[UIAlertAction actionWithTitle:@"排列章节（指定前一位置）" style:UIAlertActionStyleDefault handler:^(UIAlertAction*action){[self orderChapter:id];}]];[a addAction:[UIAlertAction actionWithTitle:@"删除章节（谱面保留）" style:UIAlertActionStyleDestructive handler:^(UIAlertAction*action){NSMutableDictionary*d=[[PMContentStore.shared snapshot]mutableCopy];NSMutableArray*c=[d[@"chapters"]mutableCopy];for(NSInteger i=c.count-1;i>=0;--i)if([c[i][@"id"] isEqualToString:id])[c removeObjectAtIndex:i];for(NSMutableDictionary*s in d[@"songs"])if([s[@"targetChapter"] isEqualToString:id])s[@"targetChapter"]=@"pm_local";if(![id isEqualToString:@"pm_local"]){d[@"chapters"]=c;[self save:d];}else[self message:@"默认收藏章节不能删除"]; }]];}
 [self sheet:a row:index];}
- (void)edit:(NSDictionary*)item chapter:(BOOL)chapter{BOOL official=self.pages.selectedSegmentIndex==2;NSArray*keys=chapter?@[@"name",@"subtitle",@"banner"]:@[@"title",@"composer",@"charter",@"illustrator",@"level",@"difficulty",@"offsetMs",@"preview",@"previewEnd"];NSArray*titles=chapter?@[@"章节名称",@"副标题",@"横幅"]:@[@"曲名",@"曲师",@"谱师",@"画师",@"难度 EZ/HD/IN/AT",@"定数",@"偏移 / ms",@"预览起点 / 秒",@"预览终点 / 秒"];UIAlertController*a=[UIAlertController alertControllerWithTitle:@"编辑信息" message:@"保存后点击应用到游戏" preferredStyle:UIAlertControllerStyleAlert];for(NSUInteger i=0;i<keys.count;++i){[a addTextFieldWithConfigurationHandler:^(UITextField*f){f.placeholder=titles[i];id value=item[keys[i]];if(official){NSString*key=[@{@"name":@"title",@"subtitle":@"subTitle",@"banner":@"banner"} objectForKey:keys[i]];value=item[@"songInfo"][key];}f.text=[value description] ?: @"";if(i>=5)f.keyboardType=UIKeyboardTypeNumbersAndPunctuation;}];}[a addAction:[UIAlertAction actionWithTitle:@"取消" style:UIAlertActionStyleCancel handler:nil]];[a addAction:[UIAlertAction actionWithTitle:@"保存" style:UIAlertActionStyleDefault handler:^(UIAlertAction*action){NSMutableDictionary*d=[[PMContentStore.shared snapshot]mutableCopy],*edited=[item mutableCopy];for(NSUInteger i=0;i<keys.count;++i){NSString*v=a.textFields[i].text ?: @"";if(!chapter&&i>=5){NSScanner*scanner=[NSScanner scannerWithString:v];double value=0;if(![scanner scanDouble:&value]||!scanner.isAtEnd||!std::isfinite(value)){[self message:@"数值格式无效"];return;}edited[keys[i]]=@(value);}else edited[keys[i]]=v;}if(!chapter&&![@[@"EZ",@"HD",@"IN",@"AT"]containsObject:edited[@"level"]]){[self message:@"难度必须为 EZ/HD/IN/AT"];return;}if(official){NSMutableDictionary*overrides=[d[@"chapterOverrides"]mutableCopy] ?: [NSMutableDictionary new];overrides[item[@"chapterCode"]]=@{@"title":edited[@"name"],@"subTitle":edited[@"subtitle"],@"banner":edited[@"banner"]};d[@"chapterOverrides"]=overrides;}else{NSMutableArray*list=[d[chapter?@"chapters":@"songs"]mutableCopy];for(NSUInteger i=0;i<list.count;++i)if([list[i][@"id"] isEqualToString:item[@"id"]])list[i]=edited;d[chapter?@"chapters":@"songs"]=list;}[self save:d];}]];[self presentViewController:a animated:YES completion:nil];}
- (void)add {if(self.busy)return;if(self.pages.selectedSegmentIndex==0){[self importFiles];return;}UIAlertController*a=[UIAlertController alertControllerWithTitle:@"新建章节" message:nil preferredStyle:UIAlertControllerStyleAlert];[a addTextFieldWithConfigurationHandler:^(UITextField*f){f.placeholder=@"章节名称";}];[a addAction:[UIAlertAction actionWithTitle:@"取消" style:UIAlertActionStyleCancel handler:nil]];[a addAction:[UIAlertAction actionWithTitle:@"创建" style:UIAlertActionStyleDefault handler:^(UIAlertAction*x){NSString*name=a.textFields.firstObject.text;if(!name.length)return;NSMutableDictionary*d=[[PMContentStore.shared snapshot]mutableCopy];NSMutableArray*c=[d[@"chapters"]mutableCopy];NSString*id=[@"pm_" stringByAppendingString:[NSUUID.UUID.UUIDString stringByReplacingOccurrencesOfString:@"-" withString:@""]];[c addObject:@{@"id":id,@"name":name,@"subtitle":@"LOCAL CHARTS",@"songs":@[]}];d[@"chapters"]=c;[self save:d];}]];[self presentViewController:a animated:YES completion:nil];}
- (void)move:(NSString*)identifier index:(NSIndexPath*)index{UIAlertController*a=[UIAlertController alertControllerWithTitle:@"选择目标章节" message:nil preferredStyle:UIAlertControllerStyleActionSheet];for(NSDictionary*c in self.db[@"chapters"])[a addAction:[UIAlertAction actionWithTitle:c[@"name"] style:UIAlertActionStyleDefault handler:^(UIAlertAction*x){NSMutableDictionary*d=[[PMContentStore.shared snapshot]mutableCopy];for(NSMutableDictionary*v in d[@"chapters"]){[v[@"songs"] removeObject:identifier];if([v[@"id"] isEqualToString:c[@"id"]])[v[@"songs"]addObject:identifier];}for(NSMutableDictionary*s in d[@"songs"])if([s[@"id"] isEqualToString:identifier])s[@"targetChapter"]=c[@"id"];[self save:d];}]];[self sheet:a row:index];}
- (void)group:(NSDictionary*)song{UIAlertController*a=[UIAlertController alertControllerWithTitle:@"多难度分组" message:@"填写另一谱面的 ID 合并为同一首；留空恢复独立。同难度多版本会以最后选择为准。" preferredStyle:UIAlertControllerStyleAlert];[a addTextFieldWithConfigurationHandler:^(UITextField*f){f.text=song[@"groupId"];f.placeholder=@"pm_... 或原版歌曲 ID";}];[a addAction:[UIAlertAction actionWithTitle:@"取消" style:UIAlertActionStyleCancel handler:nil]];[a addAction:[UIAlertAction actionWithTitle:@"保存并选用此版本" style:UIAlertActionStyleDefault handler:^(UIAlertAction*x){NSString*group=a.textFields.firstObject.text.length?a.textFields.firstObject.text:song[@"id"];NSMutableDictionary*d=[[PMContentStore.shared snapshot]mutableCopy];for(NSMutableDictionary*s in d[@"songs"])if([s[@"id"] isEqualToString:song[@"id"]])s[@"groupId"]=group;NSMutableDictionary*choices=[d[@"chartSelections"]mutableCopy] ?: [NSMutableDictionary new];NSInteger slot=[@[@"EZ",@"HD",@"IN",@"AT"]indexOfObject:song[@"level"]];choices[[NSString stringWithFormat:@"%@@%ld",group,(long)slot]]=song[@"id"];d[@"chartSelections"]=choices;[self save:d];}]];[self presentViewController:a animated:YES completion:nil];}
- (void)orderChapter:(NSString*)identifier{UIAlertController*a=[UIAlertController alertControllerWithTitle:@"排列到此章节之前" message:nil preferredStyle:UIAlertControllerStyleActionSheet];NSMutableArray*chapters=[self.db[@"chapters"]mutableCopy];[chapters addObjectsFromArray:[PMHookBackend contentSnapshot][@"chapters"] ?: @[]];for(NSDictionary*c in chapters){NSString*id=c[@"id"] ?: c[@"chapterCode"];if([id isEqualToString:identifier])continue;[a addAction:[UIAlertAction actionWithTitle:c[@"name"] ?: c[@"songInfo"][@"title"] style:UIAlertActionStyleDefault handler:^(UIAlertAction*x){NSMutableDictionary*d=[[PMContentStore.shared snapshot]mutableCopy];for(NSMutableDictionary*v in d[@"chapters"])if([v[@"id"]isEqualToString:identifier])v[@"before"]=id;[self save:d];}]];}a.popoverPresentationController.barButtonItem=self.navigationItem.rightBarButtonItem;[a addAction:[UIAlertAction actionWithTitle:@"取消" style:UIAlertActionStyleCancel handler:nil]];[self presentViewController:a animated:YES completion:nil];}
- (void)importFiles {if(self.busy)return;self.imageID=nil;UIDocumentPickerViewController*p=[[UIDocumentPickerViewController alloc]initForOpeningContentTypes:@[UTTypeData,UTTypeZIP] asCopy:NO];p.allowsMultipleSelection=YES;p.delegate=self;[self presentViewController:p animated:YES completion:nil];}
- (void)documentPicker:(UIDocumentPickerViewController*)picker didPickDocumentsAtURLs:(NSArray<NSURL*>*)urls {if(!urls.count)return;self.busy=YES;[self reload];NSString*imageID=self.imageID,*chapter=self.selectedChapter;self.imageID=nil;dispatch_async(self.worker,^{NSMutableArray*errors=[NSMutableArray new];NSUInteger done=0;for(NSURL*url in urls){@autoreleasepool{NSError*e=nil;BOOL ok;if(imageID){BOOL access=[url startAccessingSecurityScopedResource];ok=[PMContentStore.shared replaceImage:url identifier:imageID error:&e];if(access)[url stopAccessingSecurityScopedResource];}else ok=[PMContentStore.shared importURL:url chapter:chapter error:&e];if(ok)done++;else[errors addObject:[NSString stringWithFormat:@"%@: %@",url.lastPathComponent,e.localizedDescription ?: @"失败"]];}}dispatch_async(dispatch_get_main_queue(),^{self.busy=NO;[self reload];[self message:[NSString stringWithFormat:@"完成 %lu / %lu\n%@",(unsigned long)done,(unsigned long)urls.count,[errors componentsJoinedByString:@"\n"]]];});});}
- (void)export:(NSString*)identifier chapter:(BOOL)chapter {if(self.busy)return;self.busy=YES;[self reload];dispatch_async(self.worker,^{NSError*e=nil;NSURL*url=chapter?[PMContentStore.shared exportChapter:identifier error:&e]:[PMContentStore.shared exportSong:identifier error:&e];dispatch_async(dispatch_get_main_queue(),^{self.busy=NO;[self reload];if(!url){[self message:e.localizedDescription];return;}UIDocumentPickerViewController*p=[[UIDocumentPickerViewController alloc]initForExportingURLs:@[url] asCopy:YES];[self presentViewController:p animated:YES completion:nil];});});}
- (void)apply {if(self.busy)return;NSDictionary*r=[PMHookBackend contentCommand:@"apply" identifier:@"" slot:0];if([r[@"ok"] boolValue])[self dismissViewControllerAnimated:YES completion:nil];else[self message:r[@"message"]];}
@end
void PMShowContent(UIView*source,BOOL chapters){UIViewController*presenter=source.window.rootViewController;if(!presenter)return;while(presenter.presentedViewController)presenter=presenter.presentedViewController;PMContentController*c=[[PMContentController alloc]initWithStyle:UITableViewStyleInsetGrouped];UINavigationController*nav=[[UINavigationController alloc]initWithRootViewController:c];nav.modalPresentationStyle=UIModalPresentationFullScreen;[presenter presentViewController:nav animated:YES completion:^{c.pages.selectedSegmentIndex=chapters?1:0;[c reload];}];}
